 const bushGeo=new T.IcosahedronGeometry(.8,1),bushes=new T.InstancedMesh(bushGeo,new T.MeshStandardMaterial({color:0x365f32,roughness:1,vertexColors:true}),1800);for(let i=0;i<1800;i++){const x=(rnd()-.5)*305,z=(rnd()-.5)*325,scale=.45+rnd()*1.25;dummy.position.set(x,.32+scale*.22,z);dummy.rotation.set(rnd()*.3,rnd()*6.28,rnd()*.2);dummy.scale.set(scale*(.8+rnd()*.5),scale*(.45+rnd()*.35),scale*(.8+rnd()*.5));dummy.updateMatrix();bushes.setMatrixAt(i,dummy.matrix);color.setHSL(.24+rnd()*.07,.32+rnd()*.22,.18+rnd()*.14);bushes.setColorAt(i,color)}bushes.castShadow=true;bushes.receiveShadow=true;scene.add(bushes);
 const mossGeo=new T.CircleGeometry(1,9),moss=new T.InstancedMesh(mossGeo,new T.MeshStandardMaterial({color:0x3f6935,roughness:1,side:T.DoubleSide}),2300);for(let i=0;i<2300;i++){const x=(rnd()-.5)*305,z=(rnd()-.5)*325,scale=.45+rnd()*1.8;dummy.position.set(x,.025,z);dummy.rotation.set(-Math.PI/2,0,rnd()*6.28);dummy.scale.set(scale,scale*(.45+rnd()),1);dummy.updateMatrix();moss.setMatrixAt(i,dummy.matrix)}moss.receiveShadow=true;scene.add(moss);
 const ivyMat=new T.MeshStandardMaterial({color:0x47783d,roughness:1,side:T.DoubleSide}),ivy=new T.InstancedMesh(leafGeo,ivyMat,3600);for(let i=0;i<3600;i++){const x=(rnd()-.5)*305,z=(rnd()-.5)*325,scale=.22+rnd()*.55;dummy.position.set(x,.04,z);dummy.rotation.set(-Math.PI/2+(rnd()-.5)*.12,rnd()*6.28,rnd()*6.28);dummy.scale.setScalar(scale);dummy.updateMatrix();ivy.setMatrixAt(i,dummy.matrix)}ivy.receiveShadow=true;scene.add(ivy);
 const rockGeo=new T.DodecahedronGeometry(1,0),rocks=new T.InstancedMesh(rockGeo,new T.MeshStandardMaterial({color:0x5d6258,roughness:1}),600);for(let i=0;i<600;i++){const x=(rnd()-.5)*305,z=(rnd()-.5)*325,scale=.18+rnd()*.85;dummy.position.set(x,scale*.24,z);dummy.rotation.set(rnd()*1.2,rnd()*6.28,rnd()*.5);dummy.scale.set(scale,scale*(.35+rnd()*.35),scale*(.7+rnd()*.7));dummy.updateMatrix();rocks.setMatrixAt(i,dummy.matrix)}rocks.receiveShadow=true;scene.add(rocks);
 // A two-draw-call ring of distant trunks and crowns makes the forest continue into the haze.
 const distantCount=240,distantTrunks=new T.InstancedMesh(new T.CylinderGeometry(.45,1.5,28,6),mats.bark,distantCount),distantCrowns=new T.InstancedMesh(new T.IcosahedronGeometry(6,1),new T.MeshStandardMaterial({color:0x39583d,roughness:1}),distantCount);for(let i=0;i<distantCount;i++){const angle=rnd()*Math.PI*2,radius=185+rnd()*120,height=20+rnd()*20,x=Math.sin(angle)*radius,z=Math.cos(angle)*radius;dummy.position.set(x,height/2,z);dummy.rotation.set(0,rnd()*6.28,0);dummy.scale.set(1,height/28,1);dummy.updateMatrix();distantTrunks.setMatrixAt(i,dummy.matrix);dummy.position.set(x,height+3+rnd()*5,z);dummy.scale.set(1+rnd()*.7,.6+rnd()*.35,1+rnd()*.7);dummy.updateMatrix();distantCrowns.setMatrixAt(i,dummy.matrix)}distantTrunks.receiveShadow=true;distantCrowns.receiveShadow=true;scene.add(distantTrunks,distantCrowns);
 const shaftMaterial=new T.MeshBasicMaterial({color:0xffe5a2,transparent:true,opacity:.035,side:T.DoubleSide,depthWrite:false,blending:T.AdditiveBlending}),shafts=[];for(let i=0;i<8;i++){const shaft=new T.Mesh(new T.ConeGeometry(4+rnd()*5,55,10,1,true),shaftMaterial);shaft.position.set((rnd()-.5)*260,26,(rnd()-.5)*300);shaft.rotation.z=(rnd()-.5)*.16;scene.add(shaft);shafts.push(shaft)}
